CREATE INDEX "customer_service_website_public_events_keyset_idx" ON "customer_service_conversation_events" USING btree ("conversation_id","created_at","id") WHERE "customer_service_conversation_events"."channel" = 'website' and ("customer_service_conversation_events"."event_type" = 'customer_message' or ("customer_service_conversation_events"."event_type" = 'human_outbound' and "customer_service_conversation_events"."role" = 'staff'));